// The coaching course's first question bank (spec §8, decision 12.7 a): 100 original questions in
// the style of India's CAT, with worked answers. Modelled on past papers' topics, formats (including
// TITA, type-in-the-answer) and difficulty, but every question, passage and data set here was written
// for this app: none is copied from a real paper (the repo is public; past papers are the IIMs').
// The owner's own past-paper file is imported on the phone only (spec §13), never stored here.
import type { CatQuestion, CatSection, CatSet } from './types';

type Q = Omit<CatQuestion, 'id' | 'section' | 'format'>;
let n = 0;
const id = () => `q${String(++n).padStart(3, '0')}`;
const M = (section: CatSection, q: Q): CatQuestion => ({ id: id(), section, format: 'mcq', ...q });
const T = (section: CatSection, q: Q): CatQuestion => ({ id: id(), section, format: 'tita', ...q });

